import * as THREE from '../vendor/three.module.js';import {BODIES,BY_ID,LEVELS} from './architecture.js';import {toWorld,toLocal} from './pose.js';
export function visibleBodyIds(sim,mode,frustum=null){if(mode==='overview')return new Set(BODIES.map(b=>b.id));const owner=sim.owner,b=BY_ID[owner];let closed=null;if(b){const q=toLocal(sim.positions[owner],sim.player),privateRoom=b.privateRooms?.some(r=>q.x>r.x+.12&&q.x<r.x+r.w-.12&&q.z>r.z+.12&&q.z<r.z+r.d-.12);if(privateRoom&&b.doors.every(d=>!sim.doors[d.id]&&(sim.experience.doorProgress[d.id]??0)<.001))closed=new Set([owner]);}if(!closed&&sim.mode==='moving'&&sim.shutter>=.999){closed=new Set([owner]);let changed=true;while(changed){changed=false;for(const c of sim.liveConnections.filter(c=>c.permanent&&c.status!=='blocked')){if(closed.has(c.bodyA)&&!closed.has(c.bodyB)){closed.add(c.bodyB);changed=true;}if(closed.has(c.bodyB)&&!closed.has(c.bodyA)){closed.add(c.bodyA);changed=true;}}}}
 const visible=new Set();for(const body of BODIES){if(closed&&!closed.has(body.id))continue;if(body.id===owner||!frustum){visible.add(body.id);continue;}const p=sim.positions[body.id],box=new THREE.Box3();for(const [cx,cz]of body.cells)for(const x of [cx*8,cx*8+8])for(const z of [cz*8,cz*8+8])for(const y of [0,6]){const w=toWorld(p,{x,z,y});box.expandByPoint(new THREE.Vector3(w.x,w.y,w.z));}if(frustum.intersectsBox(box))visible.add(body.id);}return visible;}
export function applyBodyVisibility(view,overview){if(view.visibilityCulling===false)return;if(overview)return;view.visibilityFrustum??=new THREE.Frustum();view.visibilityMatrix??=new THREE.Matrix4();view.camera.updateMatrixWorld(true);view.visibilityMatrix.multiplyMatrices(view.camera.projectionMatrix,view.camera.matrixWorldInverse);view.visibilityFrustum.setFromProjectionMatrix(view.visibilityMatrix);const visible=visibleBodyIds(view.sim,view.mode,view.visibilityFrustum);for(const [id,group]of Object.entries(view.groups))group.visible=visible.has(id);view.visibleBodyCount=visible.size;}
